from scenario_forge.models.capability_profile import (
    CapabilityProfile as _CapabilityProfile,
    ConfidenceLevel as _ConfidenceLevel,
    EntryPoint as _EntryPoint,
    ToolInventoryEntry as _ToolInventoryEntry,
)
from scenario_forge.stpa.models.scenario_envelope import (
    SystemContext as _SystemContext,
    ConsumerHints as _ConsumerHints,
)
from scenario_forge.stpa.scenario_prod.enrichment import (
    compute_system_context as _compute_system_context,
    compute_consumer_hints as _compute_consumer_hints,
)
from scenario_forge.stpa.scenario_prod.assembly import assemble_envelope as _assemble_envelope


def _make_enrichment_control_structure(
    resp_desc: str = "Orchestrate tool calls safely",
    ca_desc: str = "Execute requested tool",
) -> ControlStructure:
    """Build a CS with RESP-1/CA-1-1 for enrichment tests."""
    return ControlStructure(
        responsibilities=[
            Responsibility(
                resp_id="RESP-1",
                description=resp_desc,
                process_model_parts=[
                    ProcessModelPart(pm_id="PM-1-1", description="State"),
                ],
                control_actions=[
                    ControlAction(
                        ca_id="CA-1-1",
                        description=ca_desc,
                        target=ElementRef(type=ReferenceType.controlled_process, id="CP-1"),
                    ),
                ],
                feedback_channels=[
                    FeedbackChannel(
                        fb_id="FB-1-1", description="Feedback", updates="PM-1-1",
                        source=ElementRef(type=ReferenceType.controlled_process, id="CP-1"),
                    ),
                ],
            ),
        ],
        controlled_processes=[ControlledProcess(cp_id="CP-1", description="Interface")],
    )


def _make_enrichment_capability_profile(
    kc_subcodes: list[str] | None = None,
    tool_inventory: list | None = None,
) -> _CapabilityProfile:
    """Build a CapabilityProfile for enrichment tests."""
    if kc_subcodes is None:
        kc_subcodes = ["KC1.1", "KC5.1", "KC6.1.1"]
    if tool_inventory is None:
        tool_inventory = [_ToolInventoryEntry(name="database_query", description="Query the database")]
    return _CapabilityProfile(
        zones_active=[],
        entry_points=[_EntryPoint(name="user prompts via chat", direction="input")],
        confidence=_ConfidenceLevel.high,
        kc_subcodes=kc_subcodes,
        tool_inventory=tool_inventory,
    )


def _h_enrichment_cs_with_resp_desc(world: World, text: str, examples: dict) -> tuple[bool, str]:
    """Handle: a control structure with responsibility RESP-1 having description ..."""
    match = re.search(r'description "([^"]+)"', text)
    resp_desc = match.group(1) if match else "Orchestrate tool calls safely"
    match2 = re.search(r'control action CA-1-1 under RESP-1 having description "([^"]+)"', text)
    ca_desc = match2.group(1) if match2 else "Execute requested tool"
    world.control_structure = _make_enrichment_control_structure(resp_desc=resp_desc, ca_desc=ca_desc)
    return True, ""


def _h_enrichment_ca_desc(world: World, text: str, examples: dict) -> tuple[bool, str]:
    """Handle: a control action CA-1-1 under RESP-1 having description ..."""
    match = re.search(r'description "([^"]+)"', text)
    ca_desc = match.group(1) if match else "Execute requested tool"
    if world.control_structure is None:
        world.control_structure = _make_enrichment_control_structure(ca_desc=ca_desc)
    return True, ""


def _h_enrichment_cap_profile_tool(world: World, text: str, examples: dict) -> tuple[bool, str]:
    """Handle: a capability profile with tool_inventory having tool ..."""
    match = re.search(r'tool "([^"]+)"', text)
    tool_name = match.group(1) if match else "database_query"
    world.capability_profile = _make_enrichment_capability_profile(
        tool_inventory=[_ToolInventoryEntry(name=tool_name, description="Tool")],
    )
    return True, ""


def _h_enrichment_cap_profile_active_zones(world: World, text: str, examples: dict) -> tuple[bool, str]:
    """Handle: the capability profile has active_zones [...]"""
    match = re.search(r'active_zones \[([^\]]+)\]', text)
    if match:
        zones_raw = match.group(1)
        zones = [z.strip().strip('"') for z in zones_raw.split(",")]
    else:
        zones = ["input", "reasoning", "tool_execution"]
    if world.capability_profile is None:
        world.capability_profile = _make_enrichment_capability_profile()
    # Set zones_active directly
    world.capability_profile = world.capability_profile.model_copy(update={"zones_active": zones})
    return True, ""


def _h_enrichment_cap_profile_multi_agent(world: World, text: str, examples: dict) -> tuple[bool, str]:
    """Handle: the capability profile has multi_agent True/False."""
    value = "True" in text or " true" in text.lower()
    if world.capability_profile is None:
        kc = ["KC1.1", "KC2.3"] if value else ["KC1.1", "KC5.1", "KC6.1.1"]
        world.capability_profile = _make_enrichment_capability_profile(kc_subcodes=kc)
    else:
        # Adjust KC subcodes to get the right multi_agent value
        kc = list(world.capability_profile.kc_subcodes)
        if value and not any(k.startswith("KC2.") for k in kc):
            kc.append("KC2.3")
        elif not value and any(k.startswith("KC2.") for k in kc):
            kc = [k for k in kc if not k.startswith("KC2.")]
        world.capability_profile = world.capability_profile.model_copy(update={"kc_subcodes": kc})
    return True, ""


