    return {
        "requirements": [
            {"req_id": "REQ-1", "description": "Verify user identity", "classification": "control", "source_constraint": "SC-1"},
            {"req_id": "REQ-2", "description": "Data protection", "classification": "constraint", "source_constraint": "SC-2"},
        ]
    }


