    m = re.search(r"new_responsibilities containing (RESP-\d+)", text)
    if not m:
        return False, f"Could not parse resp_id from: {text}"
    resp_id = m.group(1)
    # Get existing delta dict and add to it
    existing = client._response_map.get(_FCRevisionDelta, {})
