    if manifest is None:
        return False, "run-manifest.yaml not loaded"
    actual = manifest.get("stage_summary", {}).get("stage_1a", {}).get("call_count", 0)
    if actual != expected:
        return False, f"stage_1a.call_count is {actual} (expected {expected})"
    return True, ""


